window.ScripturaLexicons.BDAG_PART_0358 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-01\" data-source=\"BDAG\" data-search=\"τηγανίζω verbo fritar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τηγανίζω</td><td>verbo</td><td>fritar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-02\" data-source=\"BDAG\" data-search=\"τήκω verbo derreter; dissolver BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τήκω</td><td>verbo</td><td>derreter; dissolver</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-03\" data-source=\"BDAG\" data-search=\"τηλαυγής, ές adjetivo claro; evidente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τηλαυγής, ές</td><td>adjetivo</td><td>claro; evidente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-04\" data-source=\"BDAG\" data-search=\"τηλαυγῶς advérbio claramente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τηλαυγῶς</td><td>advérbio</td><td>claramente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-05\" data-source=\"BDAG\" data-search=\"τηλικοῦτος, αύτη, οῦτο pronome demonstrativo tão grande BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τηλικοῦτος, αύτη, οῦτο</td><td>pronome demonstrativo</td><td>tão grande</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-06\" data-source=\"BDAG\" data-search=\"τημελέω verbo cuidar de; zelar por BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τημελέω</td><td>verbo</td><td>cuidar de; zelar por</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-07\" data-source=\"BDAG\" data-search=\"τημελοῦχος, ον adjetivo protetor; que cuida BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τημελοῦχος, ον</td><td>adjetivo</td><td>protetor; que cuida</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-08\" data-source=\"BDAG\" data-search=\"τηνικαῦτα advérbio naquele tempo; então BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τηνικαῦτα</td><td>advérbio</td><td>naquele tempo; então</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-09\" data-source=\"BDAG\" data-search=\"τηρέω verbo guardar; conservar; observar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τηρέω</td><td>verbo</td><td>guardar; conservar; observar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-10\" data-source=\"BDAG\" data-search=\"τήρησις, εως, ἡ substantivo feminino custódia; cuidado; observância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τήρησις, εως, ἡ</td><td>substantivo feminino</td><td>custódia; cuidado; observância</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-11\" data-source=\"BDAG\" data-search=\"τηρητής, οῦ, ὁ substantivo masculino sentinela; guarda BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τηρητής, οῦ, ὁ</td><td>substantivo masculino</td><td>sentinela; guarda</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-12\" data-source=\"BDAG\" data-search=\"Τιβεριάς, άδος, ἡ nome próprio feminino Tiberíades BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τιβεριάς, άδος, ἡ</td><td>nome próprio feminino</td><td>Tiberíades</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-13\" data-source=\"BDAG\" data-search=\"Τιβέριος, ου, ὁ nome próprio masculino Tibério BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τιβέριος, ου, ὁ</td><td>nome próprio masculino</td><td>Tibério</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-14\" data-source=\"BDAG\" data-search=\"Τίβερις nome próprio masculino Tibre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τίβερις</td><td>nome próprio masculino</td><td>Tibre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-15\" data-source=\"BDAG\" data-search=\"τίθημι verbo pôr; depositar; designar; estabelecer; tornar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τίθημι</td><td>verbo</td><td>pôr; depositar; designar; estabelecer; tornar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-16\" data-source=\"BDAG\" data-search=\"τίκτω verbo dar à luz; produzir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τίκτω</td><td>verbo</td><td>dar à luz; produzir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-17\" data-source=\"BDAG\" data-search=\"τίλλω verbo arrancar; colher BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τίλλω</td><td>verbo</td><td>arrancar; colher</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-18\" data-source=\"BDAG\" data-search=\"Τιμαῖος, ου, ὁ nome próprio masculino Timeu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τιμαῖος, ου, ὁ</td><td>nome próprio masculino</td><td>Timeu</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-19\" data-source=\"BDAG\" data-search=\"τιμάω verbo avaliar; honrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τιμάω</td><td>verbo</td><td>avaliar; honrar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0358-20\" data-source=\"BDAG\" data-search=\"τιμή, ῆς, ἡ substantivo feminino preço; honra; remuneração; privilégio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τιμή, ῆς, ἡ</td><td>substantivo feminino</td><td>preço; honra; remuneração; privilégio</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0358-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τηγανίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τηγανίζω</span> (fritar em um <span class=\"greek\">τήγανον</span> ‘frigideira’; Posidippus Com. [III a.C.], Fgm. 5; BGU 665, 3 [I d.C.]; 2 Macc 7:5; Jos., Ant. 7, 167; empréstimo na lit. rabínica) fritar (como em uma frigideira), pass. com sentido ativo, daqueles que sofrem tormentos de fogo no inferno ApcPt 20:34.—DELG s.v. <span class=\"greek\">τάγηνον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τήκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τήκω</span> fut. <span class=\"greek\">τήξω</span> LXX; 1 aor. <span class=\"greek\">ἔτηξα</span> LXX; perf. 3 pl. (intr.) <span class=\"greek\">τετήκασι</span> (JosAs). Pass.: 2 fut. <span class=\"greek\">τακήσομαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:12</a> v.l. (2 Cl 16:3); 2 aor. <span class=\"greek\">ἐτάκην</span> LXX (Hom. et al.; LXX; En 1:6; Test12Patr; JosAs 28:10 cod. A [p. 83, 16 Bat.]; Apc4Esdr 8:23 [Fgm. c]; Jos., Bell. 5, 426; SibOr 7, 77) fazer algo tornar-se líquido, derreter (trans.); em nossa lit. pass. derreter-se (intr.), dissolver-se (intr.) (Philo, Aet. M. 110 da terra) dos <span class=\"greek\">στοιχεῖα</span> et al. no fim do mundo (Is 34:4 v.l. [citado em ApcPt, Fgm. 5]; En 1:6; TestLevi 4:1) <span class=\"greek\">στοιχεῖα</span> <span class=\"greek\">τήκεται</span> os elementos se derretem/dissolvem 2 Pt 3:12. <span class=\"greek\">τακήσονταί</span> <span class=\"greek\">τινες</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">γῆ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">μόλιβος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πυρὶ</span> <span class=\"greek\">τηκόμενος</span> alguns dos céus se derreterão, juntamente com toda a terra, que se derreterá como chumbo sobre o fogo 2 Cl 16:3 (Apollon. Rhod. 4, 1680 <span class=\"greek\">τηκομένῳ</span> <span class=\"greek\">μολίβῳ</span>). <span class=\"greek\">πᾶσα</span> <span class=\"greek\">δύναμις</span> ApcPt, Fgm. 5 (v. acima).—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τηλαυγής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τηλαυγής</span>, <span class=\"greek\">ές</span> (<span class=\"greek\">τῆλε</span> ‘longe’, <span class=\"greek\">αὐγή</span>; Pind. et al.; LXX, Philo) lit. ‘que brilha ao longe’; depois, em geral, ‘claro, evidente’ compar. neut. como adv. <span class=\"greek\">τηλαυγέστερον</span> (Diod S 1, 50, 1; Vett. Val. 54, 7f <span class=\"greek\">οἱ</span> <span class=\"greek\">παλαιοὶ</span> <span class=\"greek\">μυστικῶς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκοτεινῶς</span> <span class=\"greek\">διέγραψαν</span>, <span class=\"greek\">ἡμεῖς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τηλαυγέστερον</span>; Philo, Poster. Cai. 65) metaf. em referência à compreensão intelectual (cf. Vett. Val. acima) mais claramente Hs 6, 5, 1 (v. também <span class=\"greek\">δηλαυγῶς</span>).—DELG s.v. <span class=\"greek\">τῆλε</span>. M-M. s.v. <span class=\"greek\">τηλαυγῶ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τηλαυγῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τηλαυγῶς</span> adv. de <span class=\"greek\">τηλαυγής</span> (Strabo 17, 1, 30; POxy 886, 24 [III d.C.]; Philo, Congr. 24, 25; Cleopatra p. 15, 38) de uma imagem visual (muito) distintamente/claramente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:25</a> (v.l. <span class=\"greek\">δηλαυγῶς</span>, q.v.—B-D-F §119, 4; Rdm.2 37; v. Mlt-H. 283).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τηλικοῦτος, αύτη, οῦτο</h1><div class=\"entry-meta\"><span>pronome demonstrativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τηλικοῦτος</span>, <span class=\"greek\">αύτη</span>, <span class=\"greek\">οῦτο</span> (forma intensificada de <span class=\"greek\">τηλίκος</span> ‘tão grande’; Aeschyl., X., Pla.; CGFP 340, 1f; et al.; inscr., pap., LXX; TestSol 23:4 P; Ath.) pron. demonstrativo correlativo de <span class=\"greek\">ἡλίκος</span> (como em Diod S 10, 19, 5; Hero Alex. I p. 396, 26; 416, 1; Jos., Ant. 8, 208; 13, 5).—Sobre a forma do neut. (-<span class=\"greek\">ον</span> ou-<span class=\"greek\">ο</span>) v. B-D-F §64, 4; Rob. 290. Sobre o emprego do art. com ele B-D-F §274; Rob. 771.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> em referência ao tamanho, tão grande, tão volumoso (Polyaenus 7, 35, 1) <span class=\"greek\">θηρίον</span> Hv 4, 2, 3f. <span class=\"greek\">κῆτος</span> 4, 1, 9. <span class=\"greek\">πλοῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:4</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> em referência ao grau, tão grande/importante/poderoso etc. (Diod S 13, 41, 2 <span class=\"greek\">χειμών</span>; EpArist 312; Jos., Bell. 4, 157 <span class=\"greek\">τὸ</span> <span class=\"greek\">τηλικοῦτον</span> <span class=\"greek\">ἀσέβημα</span>; 7, 393, Ant. 14, 352; Ath.) <span class=\"greek\">σημεῖα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέρατα</span> B 4:14; 5:8. <span class=\"greek\">σεισμός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:18</a> (com <span class=\"greek\">οὕτω</span> <span class=\"greek\">μέγας</span> acrescentado pleonasticamente). <span class=\"greek\">θόρυβος</span> MPol 8:3. <span class=\"greek\">θάνατος</span> tão grande perigo de morte (<span class=\"greek\">θάνατος</span> 1c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:10</a>. <span class=\"greek\">σωτηρία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:3</a>.—DELG s.v. <span class=\"greek\">τηλίκο</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τημελέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τημελέω</span> (Eur., Pla. et al.; Sym. Ps 30:4 e Is 40:11; Philo; Jos., Ant. 1, 252; 2, 79) cuidar de, zelar por <span class=\"greek\">τινά</span> alguém (Eur., Iph. A. 731; Plut., Mor. 148d; Sext. Emp., Math. 1, 249) <span class=\"greek\">τὸν</span> <span class=\"greek\">ἀσθενῆ</span> 1 Cl 38:2.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τημελοῦχος, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τημελοῦχος</span>, <span class=\"greek\">ον</span> (cf. <span class=\"greek\">τημέλεια</span> ‘cuidado, atenção’, <span class=\"greek\">ἔχω</span>; para formações em-<span class=\"greek\">οῦχος</span> v. Buck, Reverse Index 687f) relativo a prestar cuidados, protetor, que cuida <span class=\"greek\">τημελοῦχος</span> <span class=\"greek\">ἄγγελος</span> um anjo guardião ApcPt, Fgm. 1 e 2 (de Clem. Alex., Ecl. Proph. 41, 1; 48, 1 Stählin).—DELG s.v. <span class=\"greek\">τημελέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τηνικαῦτα</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τηνικαῦτα</span> adv., a forma mais comum de <span class=\"greek\">τηνίκα</span>, naquele tempo, então (Soph., Hdt. et al.; Ael. Aristid. 53 p. 624, 23 D.) Phlm subscr.—DELG s.v. <span class=\"greek\">τηνίκα</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τηρέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τηρέω</span> imperf. <span class=\"greek\">ἐτήρουν</span>, 3 pl. <span class=\"greek\">ἐτήρουν</span> e <span class=\"greek\">ἐτήρουσαν</span> AcPl Ha 8, 11 e 13; fut. <span class=\"greek\">τηρήσω</span>; 1 aor. <span class=\"greek\">ἐτήρησα</span>; perf. <span class=\"greek\">τετήρηκα</span>, 3 pl. <span class=\"greek\">τετήρηκαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:6</a> (B-D-F §83, 1; W-S. §13, 15; Mlt. 52f; Mlt-H. 221). Pass.: imperf. <span class=\"greek\">ἐτηρούμην</span>; 1 aor. <span class=\"greek\">ἐτηρήθην</span>; perf. <span class=\"greek\">τετήρημαι</span> (Pind., Thu.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> manter sob custódia, vigiar, guardar <span class=\"greek\">τινά</span>, <span class=\"greek\">τὶ</span> alguém, algo. Um prisioneiro (Thu. 4, 30, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:36</a>, 54; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:23</a>; um edifício (v. PPetr II, 37, 1, 19 [III a.C.] <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">χῶμα</span>; PFlor 388, 32; 1 Macc 4:61; 6:50) Hs 9, 6, 2; 9, 7, 3. Pass. (Jos., Ant. 14, 366) <span class=\"greek\">Πέτρος</span> <span class=\"greek\">ἐτηρεῖτο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">φυλακῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:5</a>. Cf. 24:23; 25:4, 21b. <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">φυλακὴν</span> guardar a prisão 12:6. <span class=\"greek\">ὅπου</span> <span class=\"greek\">οἰ</span> <span class=\"greek\">κεκλεισμένοι</span> <span class=\"greek\">τηροῦνται</span> AcPl Ha 3, 20. Abs. (manter) vigilância (PSI 165, 4; 168, 9; 1 Esdr 4:11; 2 Esdr 8:29) MPol 17:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">τηροῦντες</span> os guardas (SSol 3:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:4</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> fazer com que um estado, condição ou atividade continue, manter, conservar, reservar, preservar alguém ou algo (Aristoph., Pax 201; <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁρμονίαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> Iren. 2, 33, 5 [Harv. I 380, 13])</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> para uma finalidade determinada ou um momento oportuno (Jos., Ant. 1, 97) <span class=\"greek\">τετήρηκας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">καλὸν</span> <span class=\"greek\">οἶνον</span> <span class=\"greek\">ἕως</span> <span class=\"greek\">ἄρτι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:10</a> (POxy 1757, 23 <span class=\"greek\">τήρησόν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">αὐτά</span>, <span class=\"greek\">ἕως</span> <span class=\"greek\">ἀναβῶ</span>). Cf. 12:7 (WKühne, StKr 98/99, 1926, 476f; v. CBarrett, The Gospel According to St. John ’60, 346 sobre o problema de interpretação). <span class=\"greek\">τηρηθῆναι</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σεβαστοῦ</span> <span class=\"greek\">διάγνωσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:21a</a>. <span class=\"greek\">κληρονομίαν</span> <span class=\"greek\">τετηρημένην</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οὐρανοῖς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span> (<span class=\"greek\">εἰς</span> 4g) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:4</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:4</a> (cf. TestReub 5:5 <span class=\"greek\">εἰς</span> <span class=\"greek\">κόλασιν</span> <span class=\"greek\">αἰώνιον</span> <span class=\"greek\">τετήρηται</span>), 9, 17; 3:7 (cf. Jos., Ant. 1, 97 <span class=\"greek\">τηρεῖσθαι</span> <span class=\"greek\">κατακλυσμῷ</span>); Jd 6b, 13; MPol 2:3; 11:2; 15:1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> manter etc. intacto ou imperturbado (Polyb. 6, 56, 13 a própria palavra; Herodian 7, 9, 3) <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἀγαπῶν</span> <span class=\"greek\">με</span> <span class=\"greek\">τηρηθήσεται</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:21</a> P75. <span class=\"greek\">τὴν</span> <span class=\"greek\">σφραγῖδα</span> 2 Cl 7:6. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> 14:3a (oposto a <span class=\"greek\">φθείρειν</span>). <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> 14:3b. <span class=\"greek\">τηρεῖ</span> <span class=\"greek\">ἑαυτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:18</a> v.l. <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτοῦ</span> <span class=\"greek\">παρθένον</span> conservar sua virgem inviolada como tal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.37\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:37</a> (Heraclit. Sto. 19 p. 30, 3; Achilles Tat. 8, 18, 2 <span class=\"greek\">παρθένον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κόρην</span> <span class=\"greek\">τετήρηκα</span>. SBelkin, JBL 54, ’35, 52 entende <span class=\"greek\">τηρ</span>. aqui no sentido de sustentar a própria noiva, sem manter relações conjugais.—Sobre este assunto v. a lit. s.v. <span class=\"greek\">γαμίζω</span> 1).—Com um segundo acus. (do predicativo, para indicar a condição que deve permanecer intacta; cf. M. Ant. 6, 30 <span class=\"greek\">τήρησαι</span> <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">ἁπλοῦν</span>; BGU 1141, 25 [13 a.C.] <span class=\"greek\">ἄμεμπτον</span> <span class=\"greek\">ἐμαυτὸν</span> <span class=\"greek\">ἐτήρησα</span>; Wsd 10:5; Just., D. 88, 5 <span class=\"greek\">ἀτιμωρήτους</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">τηρῆσαι</span>) <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐντολὴν</span> <span class=\"greek\">ἄσπιλον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:14</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">βάπτισμα</span> <span class=\"greek\">ἁγνόν</span> 2 Cl 6:9. <span class=\"greek\">τὴν</span> <span class=\"greek\">σφραγῖδα</span> <span class=\"greek\">ὑγιῆ</span> Hs 8, 6, 3. <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ἁγνήν</span> 2 Cl 8:4, 6. <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">θεοῦ</span> IPhld 7:2. <span class=\"greek\">σεαυτὸν</span> <span class=\"greek\">ἁγνόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:22</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:27</a>. Pass. <span class=\"greek\">ὁλόκληρον</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τηρηθείη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:23</a>. <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> conservar alguém (incólume) por meio de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:11f</a>. <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τηρήσατε</span> preservai-vos de dano, tornando possível que Deus manifeste seu amor por vós também no futuro Jd 21. <span class=\"greek\">τοῖς</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">τετηρημένοις</span> <span class=\"greek\">κλητοῖς</span> aos que foram chamados e foram conservados incólumes para Cristo, ou, caso o <span class=\"greek\">ἐν</span> antes de <span class=\"greek\">θεῷ</span> deva ser repetido, por meio de Cristo Jd 1.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> de apegar-se a algo de modo a não abandoná-lo nem perdê-lo (Diod S 17, 43, 9 <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅπλα</span>, os escudos; <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀρετήν</span> Did., Gen. 87, 4. Cf. <span class=\"greek\">τ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">μυστήρια</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐξειπεῖν</span> <span class=\"greek\">μηδενί</span> Hippol., Ref. 5, 27, 2) <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁγνείαν</span> Hm 4, 4, 3. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑνότητα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πνεύματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:3</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:7</a> (cf. Diod S 19, 42, 5 <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span>; IBM III, 587b, 5 <span class=\"greek\">ὅτι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἐτήρησα</span>; Jos., Bell. 2, 121, Ant. 15, 134). <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:15</a> (caso contrário, terá de andar nu). <span class=\"greek\">αὐτόν</span> (=<span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:18</a>. Com uma neg.: deixar de conservar firmemente = perder por descuido ou abandonar por frivolidade ou por uma compreensão deficiente do valor daquilo que se possui <span class=\"greek\">τὶ</span> algo. <span class=\"greek\">τὸ</span> <span class=\"greek\">μικρόν</span> 2 Cl 8:5 (um dito do Senhor cuja fonte literária é desconhecida). <span class=\"greek\">τὴν</span> <span class=\"greek\">ἑαυτῶν</span> <span class=\"greek\">ἀρχήν</span> (v. <span class=\"greek\">ἀρχή</span> 7) Jd 6a.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> de proteger (Pind. et al.; En 100:5) guardar <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> alguém de alguém ou de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 17:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10b</a> (cf. Pr 7:5 <span class=\"greek\">τηρεῖν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> perseverar na obediência, guardar, observar, cumprir, prestar atenção a, esp. da lei e do ensino (LXX) <span class=\"greek\">τὶ</span> algo (Polyb. 1, 83, 5 costumes jurídicos; Herodian 6, 6, 1; Just., A I, 49, 3 <span class=\"greek\">τὰ</span> <span class=\"greek\">παλαιὰ</span> <span class=\"greek\">ἔθη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:25</a> v.l.; Hs 5, 3, 9. <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> (Achilles Tat. 8, 13, 4; Tob 14:9; TestDan 5:1.—<span class=\"greek\">τ</span>. <span class=\"greek\">νόμους</span> Jos., C. Ap. 2, 273; Orig., C. Cels. 8, 10, 11; Theoph. Ant. 2, 16 [p. 140, 15]) 15:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:10</a>; Hs 8, 3, 3–5. <span class=\"greek\">τὰ</span> <span class=\"greek\">νόμιμα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Hv 1, 3, 4 (<span class=\"greek\">τηρ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">νόμιμα</span> como em Jos., Ant. 8, 395; 9, 222). <span class=\"greek\">δικαιώματα</span> <span class=\"greek\">κυρίου</span> B 10:11. <span class=\"greek\">τὰ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span> AcPl Ha 8, 11; 13. <span class=\"greek\">πάντα</span> <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐνετειλάμην</span> <span class=\"greek\">ὑμῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:20</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span> (CB I/2, 566f, n.os 467–69, lado A de um altar [313/14 d.C.] <span class=\"greek\">τηρῶν</span> <span class=\"greek\">ἐντολὰς</span> <span class=\"greek\">ἀθανάτων</span>, isto é, <span class=\"greek\">θεῶν</span>; Sir 29:1; Jos., Ant. 8, 120; Just., D. 10, 3; Iren. 1, 10, 1 [Harv. I 91, 14]) 19:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:15</a>, 21; 15:10ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:3f</a>; 3:22, 24; 5:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:17</a>; 14:12; Hm 7:5; 12, 3, 4; 12, 6, 3; Hs 5, 1, 5; 5, 3, 2; 6, 1, 4; 8, 7, 6; 10, 3, 4 (Oxy 404, 17 restauração com base nas versões lat. e etíope); cf. 5, 3, 3. Pass. 5, 3, 5a. <span class=\"greek\">τὸ</span> <span class=\"greek\">σάββατον</span> observar o sábado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:16</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">νηστείαν</span> guardar o jejum Hs 5, 3, 5b v.l.; cf. 5, 3, 9. <span class=\"greek\">τὴν</span> <span class=\"greek\">παράδοσιν</span> (Jos., Vi. 361b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:9</a> v.l. <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.51\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:51f</a>, 55; 14:23; 15:20ab; 17:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:8</a>. <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπομονῆς</span> <span class=\"greek\">μου</span> v. 10a. <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> (1 Km 15:11) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:24</a>. <span class=\"greek\">ἃ</span> <span class=\"greek\">παρελάβαμεν</span> AcPlCor 1:5. <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">προφητείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:7</a>, <span class=\"greek\">τοῦ</span> <span class=\"greek\">βιβλίου</span> <span class=\"greek\">τούτου</span> v. 9. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">προφητείᾳ</span> <span class=\"greek\">γεγραμμένα</span> 1:3. <span class=\"greek\">ὁ</span> <span class=\"greek\">τηρῶν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔργα</span> <span class=\"greek\">μου</span> aquele que leva a sério minhas obras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:26</a>. Abs., mas com o obj. facilmente suprido pelo contexto <span class=\"greek\">τήρει</span> presta-lhe atenção 3:3 (cf. Philo, Leg. All. 3, 184).—DELG. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τήρησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τήρησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τηρέω</span>; Thu. et al.; inscr., pap., LXX; Jos., Ant. 17, 205)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> ato de manter sob custódia, custódia, encarceramento (Jos., Ant. 16, 321).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> lugar de custódia, prisão (BGU 388 III, 7). Este e o sentido 1 são prováveis (cf. Thu. 7, 86, 2; Jos., Ant. 18, 235) em <span class=\"greek\">ἔθεντο</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τήρησιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:3</a>. <span class=\"greek\">ἔθεντο</span> <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τηρήσει</span> <span class=\"greek\">δημοσίᾳ</span> 5:18.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> ato de assegurar o bem-estar de outrem, cuidado GJs 9:1, 3.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> ato de perseverar na obediência, guarda, observância (Wsd 6:18) <span class=\"greek\">ἐντολῶν</span> (Sir 32:23.—<span class=\"greek\">τῶν</span> <span class=\"greek\">νόμων</span> Hierocles, Carm. Aur. 2, 2 p. 422 M.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:19</a>.—DELG s.v. <span class=\"greek\">τηρέω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τηρητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τηρητής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (desde III a.C., inclusive pap.) sentinela, guarda encarregado da detenção AcPl Ha 3, 20.—DELG s.v. <span class=\"greek\">τηρέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τιβεριάς, άδος, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τιβεριάς</span>, <span class=\"greek\">άδος</span>, <span class=\"greek\">ἡ</span> (índice de Josefo) Tiberíades, cidade na margem ocidental do lago de Genesaré, fundada por Herodes Antipas como capital de seu domínio e denominada em honra do imperador Tibério; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:23</a>. O lago de Genesaré (v. EbNestle, Der Name des Sees Tiberias: ZDPV 35, 1912, 48–50; JDuncan, The Sea of Tiberias and Its Environs: PEF 58, 1926, 15–22; 65–74; RMiddleton, Tiberias: ibid. 162f) também é chamado <span class=\"greek\">θάλασσα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Τιβεριάδος</span> (cf. o mais preciso <span class=\"greek\">λίμνη</span>: Paus. 5, 7, 4 <span class=\"greek\">λίμνην</span> <span class=\"greek\">Τιβεριάδα</span> <span class=\"greek\">ὀνομαζομένην</span>; Jos., Bell. 3, 57 <span class=\"greek\">Τιβεριὰς</span> <span class=\"greek\">λίμνη</span>; 4, 456 <span class=\"greek\">Τιβεριέων</span> <span class=\"greek\">λίμνη</span>; SibOr 12, 104 <span class=\"greek\">Τιβεριάδος</span> <span class=\"greek\">ἅλμη</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:1</a>, mais plenamente <span class=\"greek\">θάλασσα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Γαλιλαίας</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Τιβεριάδος</span> 6:1.—Baedeker, Palästina u. Syrien7 1910, 234f; Schürer II 178–82; Dalman, Orte3 1924; MAvi-Yonah, The Foundation of Tiberias: Israel Exploration Journ. 1, ’50f, 160–69; PECS 920f.—Pauly-W. VI 770–81; Kl. Pauly V 812; BHHW III, 1982f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τιβέριος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τιβέριος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> Tibério (o nome encontra-se em Diod S 15, 51, 1: <span class=\"greek\">Τιβέριος</span>, <span class=\"greek\">Ἰούλιος</span> um tribuno militar romano do IV a.C.), imperador romano (se contado a partir da morte de Augusto, reinou de 19 de agosto de 14 d.C. a 16 de março de 37; mencionado em Fílon e Josefo; também Just., A I, 13, 3; cf. SibOr 5, 20–23; v. índice de Schürer); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:1</a> situa a primeira aparição de João Batista como profeta no décimo quinto ano do reinado de Tibério. Sobre as questões cronológicas envolvidas v. Meyer I 46f; III 205f; CCichorius, ZNW 22, 1923, 16ff; HDieckmann, Die effektive Mitregentschaft des T.: Klio 15, 1919, 339–75, Das fünfzehnte Jahr des T.: BZ 16, 1924, 54–65, Das fünfzehnte Jahr des Cäsar T.: Biblica 6, 1925, 63–67; v. s.v. <span class=\"greek\">Αὔγουστος</span>. HDessau, Gesch. der röm. Kaiserzeit II 1, 1926; GBaker, Tib. Caesar 1929; ECiaceri, Tiberio ’34; CSmith, Tib. and the Rom. Empire ’42; WGolub, Tib. ’59; EKornemann, Tib. ’60; RSeager, Tib. ’72; Pauly-W. X 478–536; Kl. Pauly V 814–18; BHHW III 1983f.—Sobre a cronologia da vida de Jesus em geral: OGerhardt, Grundzüge der Chronologie Jesu Christi ’34; RHennig, D. Geburts-u. Todesjahr Jesu Christi ’36; RJewett, A Chronology of Paul’s Life ’79; RBrown, The Birth of the Messiah ’77, 547–56, The Death of the Messiah ’94, 1350–78 (lit.); KDonfried, ABD I 1011–16 (lit. 1022).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τίβερις</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τίβερις</span> , <span class=\"greek\">εως</span> ou <span class=\"greek\">ιδος</span>, <span class=\"greek\">ὁ</span> acus. <span class=\"greek\">Τίβεριν</span> (Polyb. 6, 55, 1; Strabo et al.; Just., A I, 26, 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Τίβερι</span> <span class=\"greek\">ποταμῷ</span> SibOr 5, 170) o rio Tibre Hv 1, 1, 2.—Kl. Pauly V 813f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τίθημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τίθημι</span> (Hom.+) e sua forma variante <span class=\"greek\">τιθέω</span> (Hv 1, 1, 3 e 2, 1, 2 como presente histórico; B-D-F §321; v. Rob. 318); imperf. 3 sg. <span class=\"greek\">ἐτίθει</span>, 3 pl. <span class=\"greek\">ἐτίθεσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:56</a> e <span class=\"greek\">ἐτίθουν</span> como v.l.; Ac 3:2; 4:35; Hv 3, 2, 7 (B-D-F §94, 1; Mlt-H. 202); fut. <span class=\"greek\">θήσω</span>; 1 aor. <span class=\"greek\">ἔθηκα</span> (B-D-F §95, 1; Rob. 308; 310); 2 aor. subj. <span class=\"greek\">θῶ</span>, imper. 2 pl. <span class=\"greek\">θέτε</span>, inf. <span class=\"greek\">θεῖναι</span>, part. <span class=\"greek\">θείς</span>; perf. <span class=\"greek\">τέθεικα</span>.; mais-que-perf. <span class=\"greek\">ἐτεθείκει</span> (Just., D. 78, 5). Méd.: fut. <span class=\"greek\">θήσομαι</span>; 2 aor. <span class=\"greek\">ἐθέμην</span>. Pass.: fut. 3 pl. <span class=\"greek\">τεθήσονται</span> Jer 13:16; 1 aor. <span class=\"greek\">ἐτέθην</span>; perf. <span class=\"greek\">τέθειμαι</span>, part. <span class=\"greek\">τεθειμένος</span> (Nicol. Dam.: 90 Fgm. 130, 18 p. 401, 3 Jac.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:41</a>; Hs 9, 15, 4 (sobre o perf. v. B-D-F §97, 2). A voz média geralmente não difere em sentido da ativa (B-D-F §316, 1; v. Rob. 804f). Os limites semânticos deste verbo polivalente são bastante flexíveis.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> pôr ou colocar em determinado lugar, depositar, pôr</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> at. e pass.: em geral</p><p class=\"entry-text\"><span class=\"greek\">α</span>. com acus. depositar, colocar, pôr (de lado) <span class=\"greek\">ποῦ</span> <span class=\"greek\">τεθείκατε</span> <span class=\"greek\">αὐτόν</span>; onde o depositastes? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:34</a> (já em Hom. <span class=\"greek\">τιθέναι</span> tem o sentido especial de depositar, sepultar); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.42\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:42</a>; 20:2, 13, 15. Pass. (ApcMos 42 <span class=\"greek\">ποῦ</span> <span class=\"greek\">μέλλοι</span> <span class=\"greek\">τεθῆναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σῶμα</span> <span class=\"greek\">αὐτῆς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:55</a>. <span class=\"greek\">ὅπου</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">τεθείς</span> GPt 12:51. <span class=\"greek\">λίθον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:33</a> (Is 28:16 <span class=\"greek\">ἐμβαλῶ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:6</a>; pass. B 6:2. <span class=\"greek\">θεμέλιον</span> lançar um fundamento <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:10f</a> (em linguagem figurada).—De pedras <span class=\"greek\">ἐξώτεροι</span> <span class=\"greek\">ἐτέθησαν</span> foram colocadas do lado de fora Hs 9, 8, 3; 5a (cf. c); 7. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἰσχύι</span> <span class=\"greek\">τέθεικεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κύριος</span> o Senhor (Deus) estabeleceu em força a carne dele (de Cristo) B 6:3a; cf. b (Is 50:7).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. com o acus., frequentemente suprido pelo contexto, e uma expr. preposicional estreitamente relacionada com o verbo (Herodas 4, 34 <span class=\"greek\">τιθέναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λίθους</span> <span class=\"greek\">ζοήν</span> [sic]) <span class=\"greek\">εἰς</span> <span class=\"greek\">κρύπτην</span> pôr algo em um subterrâneo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:33</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">μνημεῖον</span> depositar em um sepulcro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:29</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:9</a>. De pedras <span class=\"greek\">τιθ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκοδομήν</span> colocar na construção Hv 3, 2, 7. Pass. Hs 9, 4, 5; 9, 6, 8; cf. 9, 5, 4. Oposto a <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκοδομῆς</span> <span class=\"greek\">ἐτέθησαν</span> foram retiradas da construção 9, 8, 1. <span class=\"greek\">ἔμπροσθέν</span> <span class=\"greek\">τινος</span> GPt 4:12. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> (Gen 50:26; Jos., Ant. 14, 124; TestJob 20:9): <span class=\"greek\">ἐν</span> <span class=\"greek\">μνημείῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.60\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:60</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:29</a>; 15:46; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.53\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:16</a>. Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.41\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:41</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:56</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:37</a>. <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> (1 Km 10:25) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:18</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span> (X., Cyr. 8, 8, 16; Ezk 40:2; JosAs 3:11; Jos., Ant. 6, 15) 8:16b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:2</a>; GPt 3:8; 6:21; 12:53. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span> 8:32. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> (Ps 20:4; 1 Km 6:8; TestAbr B 5 p. 109, 18 [Stone p. 66]; JosAs 16:11; ParJer 9:32; Mel., P. 14, 90) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:21b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a> (<span class=\"greek\">θεμέλιον</span>; v. <span class=\"greek\">α</span> acima); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:13</a>. Esp. <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> ou <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> (cf. Ps 138:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:25</a> v.l.; 10:16: <span class=\"greek\">τὴν</span> <span class=\"greek\">δεξιάν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:17</a>. <span class=\"greek\">θήσω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμά</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:18</a> (=<span class=\"greek\">ἔδωκα</span> Is 42:1; <span class=\"greek\">τ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> como em Is 63:11). <span class=\"greek\">παρά</span> <span class=\"greek\">τι</span> (Plut., Mor. 176e; 3 Km 13:31) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:35</a>, 37 v.l.; 5:2. <span class=\"greek\">πρός</span> <span class=\"greek\">τι</span> (JosAs 8:4 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">στῆθος</span>) 3:2; 4:37. <span class=\"greek\">ὑπό</span> <span class=\"greek\">τι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a>; Mk 4:21; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:25</a> (v. 5a<span class=\"greek\">α</span>). <span class=\"greek\">ὑποκάτω</span> <span class=\"greek\">τινός</span> (Jer 45:12) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:16a</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:44</a> (Ps 109:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> expressões especiais</p><p class=\"entry-text\"><span class=\"greek\">α</span>. at. explicar mediante que figura de linguagem podemos apresentar (o Reino de Deus)? (isto é, como o expressarei?) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:30</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. at. tirar, entregar na lit. joanina tirar, remover <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱμάτια</span> (Hdt 1, 10, 1 <span class=\"greek\">τ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">εἵματα</span>; cf. Herodas 5, 62; Plut., Alc. 195 [8, 2]; Jos., Bell. 1, 390 <span class=\"greek\">τ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">διάδημα</span> e v. <span class=\"greek\">ἱμάτιον</span> 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:4</a>. <span class=\"greek\">τὴν</span> (<span class=\"greek\">ἑαυτοῦ</span>) <span class=\"greek\">ψυχήν</span> depor ou entregar a própria vida 10:11 e 15 (ambos v.l. <span class=\"greek\">δίδωμι</span>), 17, 18ab (ApcSed 1:5 <span class=\"greek\">τὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">θῇ</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φίλων</span>; EFascher, Z. Auslegg. v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:17</a>, 18: Deutsche Theol. ’41, 37–66); 13:37f; 15:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 J 3:16ab</a> (Appian, Bell. Civ. 4, 68 §289 <span class=\"greek\">δεξιάς</span>; SibOr 5, 157 <span class=\"greek\">τ</span>. simplesmente=<span class=\"greek\">δίδωμι</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. at. demonstrar deferência a <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">γόνατα</span> (<span class=\"greek\">σοι</span> <span class=\"greek\">γόνυ</span> <span class=\"greek\">τίθημι</span> <span class=\"greek\">γαίᾳ</span> Eur., Troad. 1307; também em lat.: genua ponere Ovid, Fasti 2, 438; Curt. 8, 7, 13; B-D-F §5, 3b) dobrar o joelho, ajoelhar-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.60\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:60</a>; 9:40; 20:36; 21:5; Hv 1, 1, 3; 2, 1, 2.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. at. colocar diante de alguém, servir (X., Mem. 3, 14, 1; JosAs 15:14 <span class=\"greek\">τράπεζαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἄρτον</span> Just., A I, 66, 4) <span class=\"greek\">οἶνον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:10</a> (Bel 11 Theod. <span class=\"greek\">οἶνον</span> <span class=\"greek\">θές</span>).</p><p class=\"entry-text\"><span class=\"greek\">ε</span>. at. e méd. ter (em mente) <span class=\"greek\">θέτε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">καρδίαις</span> seguido de inf. tomar (vossa) resolução <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:14</a>. Méd. <span class=\"greek\">ἔθεντο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">αὐτῶν</span> conservaram em mente (o acus. do obj. é suprido pelo contexto imediato) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:66</a> (1 Km 21:13). A mesma expr.=conceber algo, arquitetar algo na mente 21:14 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:4</a>. Analogamente <span class=\"greek\">ἔθετο</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παῦλος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πνεύματι</span> seguido de inf. Paulo resolveu 19:21. <span class=\"greek\">θέσθε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ὦτα</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τούτους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.44\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:44</a>.</p><p class=\"entry-text\"><span class=\"greek\">ζ</span>. at. e méd. efetuar algo, providenciar algo <span class=\"greek\">τ</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span> seguido de acus. e inf. ordenar por intermédio de alguém que … B 13:6.—<span class=\"greek\">τὸ</span> <span class=\"greek\">μέρος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὑποκριτῶν</span> <span class=\"greek\">θήσει</span> (<span class=\"greek\">μέρος</span> 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.51\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:51</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:46</a>. Méd. com acus. (GrBar 2:1 [de Deus]; Appian, Bell. Civ. 2, 106 §442 <span class=\"greek\">εὐχὰς</span> <span class=\"greek\">τίθεσθαι</span>=oferecer orações) <span class=\"greek\">βουλήν</span> chegar a uma decisão (<span class=\"greek\">βουλή</span> 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:12</a>.</p><p class=\"entry-text\"><span class=\"greek\">η</span>. méd. pôr (sob custódia) <span class=\"greek\">τίθεσθαί</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τηρήσει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:18</a>; <span class=\"greek\">ἐν</span> (<span class=\"greek\">τῇ</span>) <span class=\"greek\">φυλακῇ</span> (Gen 41:10; 42:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:3</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:25</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">φυλακήν</span> (PPetr II, 5a, 3 [III a.C.]) 12:4; <span class=\"greek\">εἰς</span> <span class=\"greek\">τήρησιν</span> (com o acus. facilmente suprido) 4:3. <span class=\"greek\">ἐν</span> <span class=\"greek\">σωτηρίῳ</span> pôr em segurança, fazer participar da salvação (com acus. a ser suprido) 1 Cl 15:6 (Ps 11:6).</p><p class=\"entry-text\"><span class=\"greek\">θ</span>. at. fornecer (um exemplo) <span class=\"greek\">ὑπόδειγμά</span> <span class=\"greek\">τινος</span> <span class=\"greek\">τιθ</span>. estabelecer um exemplo de algo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:6</a> (cf. Jos., Ant. 17, 313 <span class=\"greek\">παράδειγμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀρετῆς</span> <span class=\"greek\">τιθέναι</span>). Acrescentam-se, no dat., as pessoas em benefício ou prejuízo das quais se dá o exemplo: <span class=\"greek\">τιθέναι</span> <span class=\"greek\">πρόσκομμα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀδελφῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:13</a> (<span class=\"greek\">πρόσκομμα</span> 2b). <span class=\"greek\">σκοπὸν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">νέοις</span> <span class=\"greek\">θήσομεν</span> 2 Cl 19:1.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> at. reservar/depositar (dinheiro), pôr de lado, acumular, depositar, termo técnico da vida comercial (Demosth. 52, 3 <span class=\"greek\">ἀργύριον</span> al.; Hyperid. 5, 4; Theocr., Epigr. 14, 2; Plut., Mor. 829b; pap.) oposto a <span class=\"greek\">αἴρειν</span> retiras o que não depositaste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:21</a>; cf. v. 22. <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">τιθέτω</span> cada um deve reservar em casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:2</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> designar para determinada tarefa ou função, nomear, designar</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> colocar/nomear alguém para algo (para exercer determinada função) (quanto à construção cf. Ael. Aristid. 53 p. 636 D.: <span class=\"greek\">τοὺς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ὄντας</span> <span class=\"greek\">νόμους</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">νόμους</span> <span class=\"greek\">τ</span>.) <span class=\"greek\">τέθεικά</span> <span class=\"greek\">σε</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐθνῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:47</a> (Is 49:6); pass.: <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">ἐτέθην</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">κῆρυξ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:11</a>. Também <span class=\"greek\">τιθ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἵνα</span> designar alguém para … <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:16</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> méd. <span class=\"greek\">τίθεσθαι</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> designar alguém para algo Dg 6:10. Com acus. facilmente suprido <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:12</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> estabelecer uma disposição</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> estabelecer, dar, de uma lei (<span class=\"greek\">τιθέναι</span> <span class=\"greek\">νόμον</span> desde Soph., El. 580; IAndrosIsis, Kyme 4; o méd. <span class=\"greek\">τίθεσθαι</span> <span class=\"greek\">νόμον</span> desde Hdt. 1, 29. Ambos frequentemente em Pla.; igualmente Diod S 5, 83, 5, onde tanto a voz at. como a méd. se empregam a respeito da lei. A at. também EpArist 15; Jos., C. Ap. 1, 316, Ant. 16, 1; Ath. 34, 2. A méd. também Appian, Bell. Civ. 3, 55 §228; Jos., C. Ap. 1, 269; 2, 273; Ar. 13, 7) somente na pass. (como Pla., Leg.; 4, 705d al.; Jos., C. Ap. 2, 184; Just., D. 11, 2; Ath. 33, 1) <span class=\"greek\">ὁ</span> <span class=\"greek\">νόμος</span> <span class=\"greek\">ἐτέθη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:19</a> D.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> méd. com acus. fixar, estabelecer, determinar <span class=\"greek\">καιροὺς</span> <span class=\"greek\">οὓς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πατὴρ</span> <span class=\"greek\">ἔθετο</span> tempos que o Pai fixou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:7</a>. <span class=\"greek\">θέμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καταλλαγῆς</span> ao estabelecer entre nós a palavra da reconciliação (=confiou-nos … ; cf. Ps 104:27 <span class=\"greek\">ἔθετο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">λόγους</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:19</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἔθετο</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλη</span> Deus dispôs as partes do corpo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:18</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> fazer passar por uma mudança de experiência/condição, tornar, destinar</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> at. ou pass., quer com duplo acus., do obj. e do predicativo (Hom.+; X., Cyr. 4, 6, 3; Lucian, Dial. Marin. 14, 2; Aelian, VH13, 6; Lev 26:31; Is 5:20; Wsd 10:21; Jos., Ant. 11, 39), quer na forma <span class=\"greek\">τιθέναι</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἴ</span> <span class=\"greek\">τι</span> (cf. 3a).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. tornar alguém <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἔθηκεν</span> <span class=\"greek\">κληρονόμον</span> <span class=\"greek\">πάντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:2</a>. <span class=\"greek\">πατέρα</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">τέθεικά</span> <span class=\"greek\">σε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:17</a> (Gen 17:5). <span class=\"greek\">ἕως</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">θῶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐχθρούς</span> <span class=\"greek\">σου</span> <span class=\"greek\">ὑποπόδιον</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">σου</span> até que eu faça de teus inimigos um escabelo para teus pés (Ps 109:1): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:44</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.35\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:35</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:13</a>; a mesma citação introduzida por <span class=\"greek\">ἄχρι</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">θῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:25</a>; pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:13</a> (sobre esta expr. cf. Plut., Mor. 1097c [HAlmqvist, Pl. u. das NT ’46, 104]). Destinar, at. <span class=\"greek\">εἰ</span> <span class=\"greek\">κόλασιν</span> 1 Cl 11:1; pass., daqueles que se recusam a crer na palavra <span class=\"greek\">εἰ</span> <span class=\"greek\">ὸ̔</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐτέθησαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:8</a>; da obrigação de Paulo de aceitar seu destino em Roma <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐτέθην</span> AcPl Ha 7, 15. Cf. 3a.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. tornar algo (Mimnermus 1, 10 D.2 fazer algo tornar-se algo [adj.]: ‘Deus tornou a velhice penosa’) <span class=\"greek\">ἀδάπανον</span> <span class=\"greek\">θήσω</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:18</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> méd. com duplo acus. tornar alguém algo (Appian., Illyr. 13 §37 <span class=\"greek\">φίλον</span> <span class=\"greek\">τίθεσθαί</span> <span class=\"greek\">τινα</span>; escol. sobre Pind., O. 1, 58b; 2 Macc 5:21; Ath. 12, 2. V. também Tyrtaeus [VII a.C.] 8, 5 D.3 do homem que é chamado a odiar a própria vida [em combate]: <span class=\"greek\">ἀνὴρ</span> <span class=\"greek\">ἐχθρὴν</span> <span class=\"greek\">ψυχὴν</span> <span class=\"greek\">θέμενος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:28</a> (CClaereboets, Biblica 24, ’43, 370–87); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:28</a>. <span class=\"greek\">τίθεσθαι</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">εἲ</span> <span class=\"greek\">τι</span> destinar alguém a algo. <span class=\"greek\">ὀργήν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:9</a>.—B. 832. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τίκτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τίκτω</span> fut. <span class=\"greek\">τέξομαι</span>; 2 aor. <span class=\"greek\">ἔτεκον</span>; perf. <span class=\"greek\">τέτοκα</span> LXX; mais-que-perf. <span class=\"greek\">ἐτετόκει</span> (Just., D. 78, 5). Pass.: fut. 3 sg. <span class=\"greek\">τεχθήσεται</span> (Just., A I, 54, 8 1), part. <span class=\"greek\">τεχθησόμενος</span> (LXX; Just., A I, 33, 1); 1 aor. <span class=\"greek\">ἐτέχθην</span> (Hom.+) primariamente ‘trazer ao mundo, gerar’ (quando empregado do pai, ‘gerar’, quando empregado da mãe, ‘dar à luz’); em nossa lit.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> fazer nascer ou vir ao mundo, dar à luz, parir, com acus. <span class=\"greek\">υἱόν</span> etc. (Demetr.: 722 Fgm. 1, 3 al. Jac.; Jos., Ant. 1, 257) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:21</a>; GJs 14:2 (Ps.-Callisth. 1, 8 Filipe fica sabendo em sonho: <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνή</span> <span class=\"greek\">σου</span> <span class=\"greek\">τέξει</span> <span class=\"greek\">σοι</span> <span class=\"greek\">υἱόν</span>, <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">κυριεύσει</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμον</span> <span class=\"greek\">πάντα</span>; Apollon. Rhod. 4, 802 segundo um dito de Têmis, está destinado que Tétis venha a <span class=\"greek\">παῖδα</span> <span class=\"greek\">τεκεῖν</span> que se elevará acima de tudo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:23</a> (Is 7:14), 25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:31</a>; 2:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:4b</a>, 5, 13. Abs. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 16:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:27</a>; 2 Cl 2:1 (os dois últimos Is 54:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:2</a>, 4a; GEg 252, 49, 51 e 53; <span class=\"greek\">ὁ</span> <span class=\"greek\">χρόνος</span> ou <span class=\"greek\">αἱ</span> <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τεκεῖν</span> <span class=\"greek\">αὐτήν</span> (acus. como suj.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.57\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:57</a>; 2:6. Pass. (Petosiris, Fgm. 9 linha 93 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀχλύος</span> [névoa] <span class=\"greek\">τίκτονται</span> <span class=\"greek\">σκώληκες</span>; JosAs 17:4; ViMal 1 [p. 89, 1 Sch.]; Just., A I, 54, 8; Mel., P. 7, 53; Ath., 33, 2—V. B-D-F §76, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:11</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> fazer vir à existência, produzir, dar origem a, em imagem figurada da terra (Aeschyl., Cho. 127; Eur., Cycl. 333; Philo, Op. M. 132 <span class=\"greek\">γῆς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τικτούσης</span>) produzir <span class=\"greek\">βοτάνην</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:7</a>. Do desejo <span class=\"greek\">συλλαβοῦσα</span> <span class=\"greek\">τίκτει</span> (sobre esta combinação cf. Gen 4:17, 25; 29:35) <span class=\"greek\">ἁμαρτίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:15</a> (cf. Aeschyl., Ag. 764 <span class=\"greek\">φιλεῖ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τίκτειν</span> <span class=\"greek\">ὕβρις</span> <span class=\"greek\">ὕβριν</span>; Solon em Stob. III p. 114, 7 H. <span class=\"greek\">ἡδονὴ</span> <span class=\"greek\">λύπην</span> <span class=\"greek\">τ</span>.; Pla., Symp. 212a <span class=\"greek\">ἀρετήν</span>, Ep. 3, 315c <span class=\"greek\">ἡδονὴ</span> <span class=\"greek\">ὕβριν</span> <span class=\"greek\">τίκτουσα</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span>. A imagem é predileta de Fílon. SibOr 3, 235 <span class=\"greek\">κακὰ</span> <span class=\"greek\">τ</span>.).—B. 281. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τίλλω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τίλλω</span> imperf. <span class=\"greek\">ἔτιλλον</span>; part. aor. <span class=\"greek\">τίλας</span> (ApcrEzek [Epiph. 70, 10]). Pass. gen. do part. perf. <span class=\"greek\">τετιλμένου</span> Is 18:7; aor. 3 sg. <span class=\"greek\">ἐτίλη</span> Da 7:4 (Hom. et al.; pap., LXX; PsSol 13:3; AscIs 2:11) arrancar, colher <span class=\"greek\">τὶ</span> algo (Diod S 5, 21, 5 <span class=\"greek\">τοὺς</span> <span class=\"greek\">παλαιοὺς</span> <span class=\"greek\">στάχυς</span> <span class=\"greek\">τίλλειν</span>; <span class=\"greek\">τίλλ</span>. <span class=\"greek\">χόρτον</span>: PFlor 321, 47; 322, 20.—Philo, Leg. ad Gai. 223, De Jos. 16) <span class=\"greek\">στάχυας</span> espigas de trigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:1</a>.—Dalman, Arbeit II 339; BCohen, The Rabb. Law Presupp. by Mt 12:1 and Lk 6:1: HTR 23, 1930, 91f; Murmelstein (v. sobre <span class=\"greek\">σπόριμος</span>).—DELG. M-M. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τιμαῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τιμαῖος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> Timeu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:46</a> (v. <span class=\"greek\">Βαρτιμαῖος</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τιμάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τιμάω</span> (<span class=\"greek\">τιμή</span>) fut. <span class=\"greek\">τιμήσω</span>; 1 aor. <span class=\"greek\">ἐτίμησα</span>; perf. 2 pl. <span class=\"greek\">τετιμήκατε</span> (Tat.). Méd.: 1 aor. <span class=\"greek\">ἐτιμησάμην</span>. Pass.: 1 fut. 3 sg. <span class=\"greek\">τιμηθήσεται</span>; 1 aor. 3 sg. <span class=\"greek\">ἐτιμήθη</span> LXX; perf. <span class=\"greek\">τετίμημαι</span>, part. <span class=\"greek\">τετιμημένος</span> (<span class=\"greek\">τιμή</span>; Hom.+).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> atribuir um preço a, estimar, avaliar (Thu. et al.; inscr.; PSI 382, 15 [I a.C.]; PFlor 266, 6 al.) pass. <span class=\"greek\">τὴν</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τετιμημένου</span> (subentende-se <span class=\"greek\">ἀγροῦ</span> ou <span class=\"greek\">ἀνθρώπου</span>, este último referente a Judas) o preço do campo ou do homem cujo preço foi fixado (<span class=\"greek\">τιμή</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:9a</a>. Méd. atribuir um preço a ou avaliar para si (Hdt. et al.; Mitt-Wilck I/2, 224a, 8; c, 8f; 11 [III a.C.]; PHal 1, 201; 205 e frequentemente nos pap.; Lev 27:8; Jos., Ant. 5, 79; Mel., P. 89, 668ff) <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἐτιμήσαντο</span> aquele (=campo ou pessoa) ao qual haviam atribuído um preço v. 9b.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> demonstrar grande estima por, honrar, reverenciar <span class=\"greek\">τινά</span> alguém. Deus (X., Mem. 4, 3, 13; Diod S 6, 1, 4; 8 <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεούς</span>; Strabo 16, 2, 35; Dio Chrys. 16 [33], 45; 58 [75], 8; Ael. Aristid. 13 p. 297 D.: <span class=\"greek\">πρὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γονέων</span>; frequente em inscrições honoríficas, v. índices nos diversos corpora, também New Docs 3, 37 n.º 9, 3 [96/97 d.C.]; Is 29:13; EpArist 234; Philo; Jos., Ant. 9, 153; 256; Just., A I, 9, 1; Orig., C. Cels. 8, 56, 35) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:6</a>; 1 Cl 15:2; 2 Cl 3:5; cf. 3:4.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:23bd</a>; 8:49 (Jesus honra seu Pai). Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:23ac</a>. Sobre GPt 3:9 v. <span class=\"greek\">τιμή</span> 2a (cf. Just., A I, 6, 2; 13, 3). Pais (Ex 20:12; também Ar. 15, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:4</a>; 19:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:10</a>; 10:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:2</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:6</a>. Anciãos (membros mais idosos da comunidade) 1 Cl 21:6. O supervisor (<span class=\"greek\">ἐπίσκοπος</span>) ISm 9:1a. Mestre da palavra divina D 4:1. Aquelas que são realmente viúvas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:3</a> (embora o sentido de <span class=\"greek\">τιμή</span> 3 possa influir aqui; cf. Sir 38:1). <span class=\"greek\">πάντας</span> (JWilson, ET 54, ’42/43, 193f), <span class=\"greek\">τὸν</span> <span class=\"greek\">βασιλέα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:17ab</a>. (Oposto a <span class=\"greek\">προσκυνέω</span> Theoph. Ant. 1, 11 [p. 82, 5]). <span class=\"greek\">τ</span>. <span class=\"greek\">πολλαῖς</span> <span class=\"greek\">τιμαῖς</span> (<span class=\"greek\">τιμή</span> 2a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:10</a>; cf. GPt 3:9. Abs. Dg 5:15.—De Deus (Soph., Fgm. 226 TGF <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">τιμᾷ</span> <span class=\"greek\">θεός</span>; pass. 4 Macc 17:20) ou de Cristo: honrar ou recompensar os cristãos (assim Isocr. 9, 42; X., An. 1, 9, 14; 5, 8, 25, Cyr. 3, 3, 6; Diod S 2, 3, 2 <span class=\"greek\">τιμᾶν</span> <span class=\"greek\">δώροις</span>; 2, 6, 9; 14, 42, 1; 16, 13, 1; Ps.-Callisth. 2, 1, 2 <span class=\"greek\">τιμάω</span> <span class=\"greek\">τινὰ</span> <span class=\"greek\">χρυσῷ</span>; pass. Hdt. 7, 213; Lys. 12, 64; 19, 18; Diod S 15, 74, 1.—Sobre a recompensa das pessoas devotas por Deus: Ps.-Aristot., Mund. 6, 23 <span class=\"greek\">τιμᾶν</span>; Simplicius, In Epict. p. 79, 11 Düb. <span class=\"greek\">τιμᾶν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κολάζειν</span>; Mel., P. 73, 535 <span class=\"greek\">ἠτίμησας</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τιμήσαντά</span> <span class=\"greek\">σε</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:26</a>; 1 Cl 59:3; IPhld 11:2; pass. ISm 9, 1b.—Os oficiais de uma congregação são chamados <span class=\"greek\">οἱ</span> <span class=\"greek\">τετιμημένοι</span> <span class=\"greek\">ὑμῶν</span> (gen. partitivo) os homens honrados entre vós D 15:2 (<span class=\"greek\">οἱ</span> <span class=\"greek\">τετιμημένοι</span> de pessoas de elevada posição: X., Cyr. 8, 3, 9). Para <span class=\"greek\">ἡ</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τετιμημένη</span> <span class=\"greek\">λειτουργία</span> 1 Cl 44:6 v. <span class=\"greek\">λειτουργία</span> 1b.—DELG s.v. <span class=\"greek\">τιμή</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0358-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τιμή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τιμή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (v. <span class=\"greek\">τιμάω</span>; Hom.+; empréstimo na lit. rabínica).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> o montante pelo qual algo é avaliado, preço, valor (v. ApcMos 18 <span class=\"greek\">νόησον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τιμήν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ξύλου</span> a árvore do Éden), esp. preço de venda (Hdt. et al.; O. Wilck II, 318, 3; POxy 1382, 18 [II d.C.]) <span class=\"greek\">συνεψήφισαν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">τιμὰς</span> <span class=\"greek\">αὐτῶν</span> (v. <span class=\"greek\">συμψηφίζω</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:19</a>. Também concretamente o preço recebido pela venda de algo 5:2. Com o gen. daquilo pelo qual se paga o preço (Is 55:1; Jos., Vi. 153, Ant. 4, 284; TestZeb 3:2) <span class=\"greek\">ἡ</span> <span class=\"greek\">τιμὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χωρίου</span> o preço pago pelo terreno v. 3. <span class=\"greek\">ἡ</span> <span class=\"greek\">τιμὴ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τετιμημένου</span> (<span class=\"greek\">τιμάω</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:9</a>. <span class=\"greek\">τιμὴ</span> <span class=\"greek\">αἵματος</span> o dinheiro pago por um ato sanguinário (<span class=\"greek\">αἷμα</span> 2a), preço de sangue v. 6. Pl. (Diod S 5, 71, 3; 6=prêmio, preço, recompensa) <span class=\"greek\">τὰς</span> <span class=\"greek\">τιμὰς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πιπρασκομένων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:34</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">τιμὰς</span> <span class=\"greek\">αὐτῶν</span> os preços que receberam por si mesmos 1 Cl 55:2.—Com o gen. de preço <span class=\"greek\">ᾧ</span> (por atração do rel. em lugar de <span class=\"greek\">ὅ</span>) <span class=\"greek\">ὠνήσατο</span> <span class=\"greek\">Ἀβραὰμ</span> <span class=\"greek\">τιμῆς</span> <span class=\"greek\">ἀργυρίου</span> que Abraão havia comprado por uma soma em prata <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:16</a>. Abs. <span class=\"greek\">τιμῆς</span> por um preço, em dinheiro (Hdt. 7, 119; PTebt 5, 185; 194; 220 [118 a.C.]; BGU 1002, 13 <span class=\"greek\">δέδωκά</span> <span class=\"greek\">σοι</span> <span class=\"greek\">αὐτὰ</span> <span class=\"greek\">τιμῆς</span>.—B-D-F §179, 1; Rob. 510f; Dssm., LO 275f [LAE 323f]) <span class=\"greek\">ἠγοράσθητε</span> <span class=\"greek\">τιμῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:20</a>; 7:23 (<span class=\"greek\">ἀγοράζω</span> 2).—<span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τιμῇ</span> <span class=\"greek\">τινι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:23</a> pode ser um latinismo (cf. Ovid, Fasti 5, 316 nec in pretio fertilis hortus; Livy 39, 6, 9; Seneca, Ep. 75, 11. V. Lohmeyer ad loc.) não têm valor algum (NRSV). V. também s.v. <span class=\"greek\">πλησμονή</span>.—GBornkamm, TLZ 73 ’48, col. 18, 2 observa que <span class=\"greek\">τ</span>. aqui nada tem que ver com ‘honra’, como tem na expr. <span class=\"greek\">ἐν</span> <span class=\"greek\">τιμῇ</span> <span class=\"greek\">εἶναι</span> X., An. 2, 5, 38; Herodian 4, 2, 9; Arrian, Anab. 4, 21, 10; Lucian, De Merc. Cond. 17.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> manifestação de estima, honra, reverência</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> at., a demonstração de honra, reverência ou respeito como ação (X., Cyr. 1, 6, 11; Diod S 17, 76, 3; Herodian 4, 1, 5; 2 Macc 9:21; Just., A I, 13, 1; Tat. 32, 1; Ath. 30, 2; Theoph. Ant. 1, 11 [p. 82, 5]; geralmente como louvor pelo desempenho; v. Reader, Polemo 280) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:1</a>. <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">τιμῇ</span> <span class=\"greek\">τιμήσωμεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> GPt 3:9. Assim talvez <span class=\"greek\">τῇ</span> <span class=\"greek\">τιμῇ</span> <span class=\"greek\">ἀλλήλους</span> <span class=\"greek\">προηγούμενοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:10</a> (v. <span class=\"greek\">προηγέομαι</span> 3). Pl. <span class=\"greek\">οἵ</span> <span class=\"greek\">πολλαῖς</span> <span class=\"greek\">τιμαῖς</span> <span class=\"greek\">ἐτίμησαν</span> <span class=\"greek\">ἡμᾶς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:10</a> (cf. Diod S 11, 38, 5 <span class=\"greek\">τιμαῖς</span> <span class=\"greek\">ἐτίμησε</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Γέλωνα</span>; OGI 51, 13 <span class=\"greek\">τοὺς</span> <span class=\"greek\">τοιούτους</span> <span class=\"greek\">τιμᾶν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">πρεπούσαις</span> <span class=\"greek\">τιμαῖς</span>; Jos., Ant. 20, 68. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:4</a> <span class=\"greek\">τιμή</span> pode muito bem ser entendida neste sentido, se <span class=\"greek\">σκεῦος</span> se refere a um membro feminino da casa; v. também c.—Quanto às <span class=\"greek\">τιμαί</span> devidas ao médico, v. Sir 38:1; v. 3 abaixo). Das manifestações de reverência que caracterizam o culto politeísta (OGI 56, 9 <span class=\"greek\">αἱ</span> <span class=\"greek\">τιμαὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>; Himerius, Or. 8 [=23], 11 <span class=\"greek\">ἡ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">τιμή</span>.—V. Orig., C. Cels. 8, 57, 29) Dg 2:8; culto judaico 3:5a.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> pass. o respeito de que alguém desfruta, honra como posse. Aos crentes é prometida <span class=\"greek\">τιμή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a> (é-lhes dada juntamente com Cristo, a <span class=\"greek\">λίθος</span> <span class=\"greek\">ἔντιμος</span> v. 6), mas v. 4 abaixo; cf. IMg 15. <span class=\"greek\">τιμὴν</span> <span class=\"greek\">ἔχειν</span> ser honrado (Hdt. 1, 168) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:3</a>. <span class=\"greek\">τιμήν</span> <span class=\"greek\">τινι</span> (<span class=\"greek\">ἀπο</span>)<span class=\"greek\">διδόναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:9</a> (com <span class=\"greek\">δόξαν</span>). <span class=\"greek\">τιμήν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">ἀπονέμειν</span> (Ath. 32, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:7</a>; 1 Cl 1:3; MPol 10:2. <span class=\"greek\">τιμήν</span> <span class=\"greek\">τινι</span> <span class=\"greek\">περιτιθέναι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:23</a>. <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">τιμήν</span> (com <span class=\"greek\">δόξαν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:17</a>; (com <span class=\"greek\">δόξαν</span> e <span class=\"greek\">δύναμιν</span>; cf. FPfister, Philol 84, 1929, 1–9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:11</a>; 5:12 (com <span class=\"greek\">δύναμις</span>, como em Plut., Mor. 421e: a divindade concede ambas se invocada por seus diversos nomes). <span class=\"greek\">τ</span>. <span class=\"greek\">τιμῆς</span> <span class=\"greek\">μεταλαβεῖν</span> Dg 3:5b. <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">περιποιεῖσθαι</span> Hm 4, 4, 2 (com <span class=\"greek\">δόξαν</span>).—<span class=\"greek\">εἰς</span> <span class=\"greek\">τιμήν</span> para honra=para ser honrado <span class=\"greek\">σκεῦος</span>, um vaso que é honrado (ou desonrado) pelo uso a que se destina <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:20f</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τιμήν</span> <span class=\"greek\">τινος</span> para honra de alguém=para que a pessoa seja honrada (Cornutus 28 p. 55, 7 <span class=\"greek\">εἰς</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Δήμητρος</span>; OGI 111, 26 <span class=\"greek\">εἰς</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">Πτολεμαίου</span>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Αἰώνων</span> Iren. 1, 5, 1 [Harv. I 42, 16]; <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γονέων</span> Did., Gen. 50, 21) IEph 2:1; 21:1, 2; IMg 3:2; ITr 12:2; ISm 11:2; IPol 5:2b; cf. v. 2a (<span class=\"greek\">εἰς</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>). Sobre <span class=\"greek\">εἰς</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τιμῆς</span> IPhld 11:2 v. <span class=\"greek\">λόγος</span> 2c.—Uma característica notável do emprego de <span class=\"greek\">τ</span>., como já demonstrado em várias passagens, é sua combinação com <span class=\"greek\">δόξα</span> (Dio Chrys. 4, 116; 27 [44], 10; Appian, Bell. Civ. 3, 18 §68; Arrian, Ind. 11, 1; Plut., Mor. 486b; Jos., Ant. 12, 118; Iren. 1, 2, 6 [Harv. I 23, 8]): de bens terrenos <span class=\"greek\">τὴν</span> <span class=\"greek\">δόξαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐθνῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:26</a> (<span class=\"greek\">τιμή</span> concr.=um objeto de valor: Ezk 22:25). Da posição singular do governante, concedida por Deus 1 Cl 61:1, 2 (na última passagem com <span class=\"greek\">ἐξουσία</span>). Sobretudo de bens celestiais: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:7</a> (com <span class=\"greek\">ἀφθαρσία</span>), v. 10 (com <span class=\"greek\">εἰρήνη</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:7</a> (com <span class=\"greek\">ἔπαινος</span>); 1 Cl 45:8. Cristo é (segundo Ps 8:6) coroado de <span class=\"greek\">δόξα</span> e <span class=\"greek\">τιμή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:7</a>, 9. Deus é chamado (entre muitos outros predicados) <span class=\"greek\">φῶς</span>, <span class=\"greek\">τιμή</span>, <span class=\"greek\">δόξα</span>, <span class=\"greek\">ἰσχύς</span>, <span class=\"greek\">ζωή</span> Dg 9:6.—Daí, esp. nas fórmulas doxológicas (Deus como destinatário de <span class=\"greek\">τ</span>.: Eur., Bacch. 323 <span class=\"greek\">θεῷ</span> <span class=\"greek\">τιμὴν</span> <span class=\"greek\">διδόναι</span>; Paus. 9, 13, 2; Ps 28:1 [com <span class=\"greek\">δόξα</span>]; 95:7 [com <span class=\"greek\">δόξα</span>]; TestAbr B 14 p. 119, 3 [Stone p. 86]; ApcEsdr 7:16 [com <span class=\"greek\">δόξα</span>, <span class=\"greek\">κράτο</span>]; Philo; Jos., C. Ap. 2, 206) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:17</a> (com <span class=\"greek\">δόξα</span>); 6:16 (com <span class=\"greek\">κράτος</span> <span class=\"greek\">αἰώνιον</span>); com <span class=\"greek\">δόξα</span> e <span class=\"greek\">κράτος</span> Jd 25 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:13</a> (com <span class=\"greek\">δόξα</span> et al.); 7:12 (com <span class=\"greek\">δόξα</span> et al.); 1 Cl 64 (com <span class=\"greek\">δόξα</span> et al.); 65:2 (com <span class=\"greek\">δόξα</span> et al.); MPol 20:2; 21 (ambos com <span class=\"greek\">δόξα</span> et al.).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> como estado de ser, respeitabilidade (cf. <span class=\"greek\">τίμιος</span> 1c) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:4</a> (com <span class=\"greek\">ἁγιασμός</span>). Se <span class=\"greek\">τιμή</span> deve ser entendida aqui como nomen actionis, a passagem pertence a a.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> posição de honra, cargo (honorífico) (Hom. et al. [v. FBleek sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:4</a>]; pap. Em Josefo, do cargo de sumo sacerdote: Ant. 12.42 <span class=\"greek\">Ἐλεαζάρῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀρχιερεῖ</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">λαβόντι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τιμήν</span>; 157 e frequentemente) <span class=\"greek\">οὐχ</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">τις</span> <span class=\"greek\">λαμβάνει</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">τιμήν</span> ninguém assume o cargo por iniciativa própria Hb 5:4.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> honra conferida mediante remuneração, honorário, remuneração (testamento de Lícon [III a.C.] Fgm. 15 W., em Diog. L. 5, 72, honorários de um médico; Sir 38:1; v. 2a acima), assim provavelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:17</a> (MDibelius, Hdb. ad loc. e v. s.v. <span class=\"greek\">διπλοῦς</span>).—O sentido 2b também é possível. Nesse caso cf. Ael. Aristid. 32, 3 K.=12 p. 134 D.: <span class=\"greek\">διπλῇ</span> <span class=\"greek\">τιμῇ</span> <span class=\"greek\">τιμῆσαι</span>.—MGreindl (v. <span class=\"greek\">δόξα</span>, final).</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> direito especialmente conferido, privilégio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a> (FDanker, ZNW 58, ’67, 96), diferentemente REB ‘tem grande valor’; NRSV ‘é precioso’.—B. 825; 1143. DELG. M-M. EDNT. TW. Sv.</p></section></article>"};
